ucation_g11_s2_2025","printed_pages":[167],"pdf_pages":[167]}},"uses":[[0],[2],[3],[5],[6],[10]]},{"data":{"id":"u04_l05_q004","unit_id":"u04","lesson_id":"u04_l05","difficulty":"medium","type":"multiple_choice","prompt":"أي دافع يدل عليه الوعد بتنفيس كربة الآخرة عمن ينفس كربة مؤمن في الدنيا؟","topic":"المفهوم والدوافع","payload":{"options":[{"id":"o1","text":"الخوف من خسارة منصب"},{"id":"o2","text":"طلب الأجر والثواب"},{"id":"o3","text":"تحقيق الشهرة وحدها"},{"id":"o4","text":"التفاخر بالمال"}]},"answer":{"option_id":"o2"},"explanation":"ورد الحديث دليلا على دافع الحرص على الأجر والثواب.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[167],"pdf_pages":[167]}},"uses":[[0],[2],[3],[5],[6],[10]]}]$educational_content$::jsonb) item
